        phbr: { name: 'bromobenzene', smiles: 'Brc1ccccc1', cas: '108-86-1', mw: 157.01, density: 1.495, role: 'the aryl halide' },
        phmgbr: { name: 'phenylmagnesium bromide', smiles: 'Br[Mg]c1ccccc1', formula: 'C6H5BrMg', cas: '100-58-3', mw: 181.31, role: 'the Grignard reagent (not isolated)' },
        bzp: { name: 'benzophenone', smiles: 'O=C(c1ccccc1)c1ccccc1', cas: '119-61-9', mw: 182.22, role: 'the ketone (limiting)' },
