          contents: { fl: { label: 'p-aminophenol hydrochloride — a very dark solution', color: 0x3b2a20, items: [{ key: 'pap', g: 2.1, note: 'as its hydrochloride' }, { key: 'water', ml: 35 }, { key: 'hcl', ml: 1.5 }], ml: 37 } },
