        ovan: { name: 'o-vanillin (2-hydroxy-3-methoxybenzaldehyde)', smiles: 'COc1cccc(C=O)c1O', cas: '148-53-8', mw: 152.15, role: 'the aldehyde' },
        imine: { name: 'the imine (Schiff base) of o-vanillin and p-toluidine', smiles: 'COc1cccc(/C=N/c2ccc(C)cc2)c1O', mw: 241.29, role: 'intermediate' },
        etoh95: Object.assign({}, S.etoh95, { role: 'solvent for the reduction' }),
        nabh4: { name: 'sodium borohydride', smiles: '[Na+].[BH4-]', formula: 'NaBH4', cas: '16940-66-2', mw: 37.83, role: 'reducing agent (a hydride source)' },
        amine: { name: 'the secondary amine', smiles: 'COc1cccc(CNc2ccc(C)cc2)c1O', mw: 243.31, role: 'intermediate' },
        acoh: Object.assign({}, S.acoh, { name: 'acetic acid (glacial)', role: 'solvent for the acetylation' }),
